<?php
require __DIR__.'/app/bootstrap.php';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$id=(int)($_POST['product_id']??0);$s=db()->prepare("SELECT id FROM products WHERE id=? AND status='active'");$s->execute([$id]);if($s->fetchColumn()){if(!empty($_SESSION['customer_id'])){$s=db()->prepare('INSERT IGNORE INTO wishlists(customer_id,product_id) VALUES(?,?)');$s->execute([$_SESSION['customer_id'],$id]);}else{$_SESSION['wishlist']=array_values(array_unique(array_merge($_SESSION['wishlist']??[],[$id])));}}header('Location: '.url('wishlist.php'));exit;}
if(isset($_GET['remove'])){$id=(int)$_GET['remove'];if(!empty($_SESSION['customer_id'])){$s=db()->prepare('DELETE FROM wishlists WHERE customer_id=? AND product_id=?');$s->execute([$_SESSION['customer_id'],$id]);}else{$_SESSION['wishlist']=array_values(array_diff($_SESSION['wishlist']??[],[$id]));}header('Location: '.url('wishlist.php'));exit;}
$ids=[];if(!empty($_SESSION['customer_id'])){$s=db()->prepare('SELECT product_id FROM wishlists WHERE customer_id=?');$s->execute([$_SESSION['customer_id']]);$ids=array_map('intval',$s->fetchAll(PDO::FETCH_COLUMN));}else{$ids=array_map('intval',$_SESSION['wishlist']??[]);}
$items=[];if($ids){$marks=implode(',',array_fill(0,count($ids),'?'));$s=db()->prepare("SELECT * FROM products WHERE status='active' AND id IN ($marks)");$s->execute($ids);$items=$s->fetchAll();}
$pageTitle='Wishlist — NEXT TECH';require __DIR__.'/includes/header.php';?>
<section class="page-intro"><span class="eyebrow">SAVED ITEMS</span><h1>Wishlist</h1></section>
<?php if($items):?><div class="product-grid"><?php foreach($items as $p):?><article class="product-card"><a href="<?=e(url('product.php?slug='.rawurlencode($p['slug'])))?>"><div class="product-image"><?php if($p['image']):?><img src="<?=e(url('uploads/products/'.$p['image']))?>" alt="<?=e($p['name'])?>"><?php else:?><span>◇</span><?php endif;?></div><h3><?=e($p['name'])?></h3></a><p class="price"><?=money($p['price'])?></p><div class="card-actions"><form method="post" action="<?=e(url('cart.php'))?>"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="product_id" value="<?=(int)$p['id']?>"><button class="btn btn-primary" name="add" value="1">Add to Cart</button></form><a class="text-link" href="<?=e(url('wishlist.php?remove='.(int)$p['id']))?>">Remove</a></div></article><?php endforeach;?></div><?php else:?><p class="empty-state">Your wishlist is empty. Save products to find them here.</p><?php endif;?>
<?php require __DIR__.'/includes/footer.php';?>